-- WELL SPA Relational SQL Schema & Data Script
-- Compatible with SQLite and standard SQL tools (no credential hashes included)
-- Generated: 2026-11-16T01:22:30.585Z
BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS studios (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT,
  tagline TEXT,
  address TEXT,
  phone TEXT,
  timezone TEXT,
  open_hour TEXT,
  close_hour TEXT,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS app_users (
  id TEXT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL,
  is_primary INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  permissions_json TEXT NOT NULL,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS rooms (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  room_type TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  notes TEXT,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS services (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL,
  buffer_minutes INTEGER NOT NULL DEFAULT 15,
  price INTEGER NOT NULL,
  room_type TEXT,
  description TEXT,
  active INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS staff (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  role TEXT NOT NULL,
  specialty TEXT,
  bio TEXT,
  avatar_url TEXT,
  assigned_room_id TEXT,
  assigned_room TEXT,
  work_days_json TEXT,
  shift_start TEXT,
  shift_end TEXT,
  break_start TEXT,
  break_end TEXT,
  on_duty INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS membership_tiers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  target_audience TEXT,
  price INTEGER NOT NULL,
  credits_included INTEGER NOT NULL,
  retail_discount_percent INTEGER NOT NULL DEFAULT 0,
  priority_window_hours INTEGER NOT NULL DEFAULT 0,
  perks_summary TEXT,
  active INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS clients (
  id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  notes TEXT,
  preferred_therapist_id TEXT,
  membership_tier_id TEXT,
  membership_tier_name TEXT,
  membership_status TEXT NOT NULL DEFAULT 'none',
  credits_remaining INTEGER NOT NULL DEFAULT 0,
  next_renewal_date TEXT,
  total_visits INTEGER NOT NULL DEFAULT 0,
  lifetime_spend INTEGER NOT NULL DEFAULT 0,
  sms_opt_in INTEGER NOT NULL DEFAULT 1,
  email_opt_in INTEGER NOT NULL DEFAULT 1,
  created_at TEXT
);

CREATE TABLE IF NOT EXISTS appointments (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL,
  client_name TEXT NOT NULL,
  client_email TEXT,
  client_phone TEXT,
  service_id TEXT NOT NULL,
  service_name TEXT NOT NULL,
  staff_id TEXT NOT NULL,
  staff_name TEXT NOT NULL,
  room_name TEXT,
  date TEXT NOT NULL,
  start_time TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL,
  price INTEGER NOT NULL,
  used_membership_credit INTEGER NOT NULL DEFAULT 0,
  credits_used INTEGER NOT NULL DEFAULT 0,
  amount_paid INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL,
  notes TEXT,
  confirmation_sent INTEGER NOT NULL DEFAULT 0,
  reminder_sent INTEGER NOT NULL DEFAULT 0,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS credit_deductions (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL,
  client_name TEXT NOT NULL,
  category TEXT NOT NULL,
  description TEXT NOT NULL,
  credits_deducted INTEGER NOT NULL,
  recorded_by_email TEXT,
  date TEXT NOT NULL,
  created_at TEXT
);

CREATE TABLE IF NOT EXISTS notification_rules (
  id TEXT PRIMARY KEY,
  event_key TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  channel TEXT NOT NULL,
  timing_label TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  subject_template TEXT,
  body_template TEXT,
  sent_count INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS notification_logs (
  id TEXT PRIMARY KEY,
  rule_id TEXT,
  event_key TEXT,
  appointment_id TEXT,
  client_id TEXT NOT NULL,
  client_name TEXT NOT NULL,
  recipient_contact TEXT,
  channel TEXT NOT NULL,
  subject TEXT,
  message_body TEXT,
  status TEXT NOT NULL,
  scheduled_for TEXT,
  sent_at_label TEXT,
  created_at TEXT
);

